bool TeamSubscription::validateJsonForCreation(const Json::Value &pJson, std::string &err)
{

    if(pJson.isMember("id"))
    {
        if(!validJsonOfField(0, "id", pJson["id"], err, true))
            return false;
    }

    if(pJson.isMember("team_id"))
    {
        if(!validJsonOfField(1, "team_id", pJson["team_id"], err, true))
            return false;
    }

    else
    {
        err="The team_id column cannot be null";
        return false;
    }

    if(pJson.isMember("plan"))
    {
        if(!validJsonOfField(2, "plan", pJson["plan"], err, true))
            return false;
    }

    if(pJson.isMember("start_date"))
    {
        if(!validJsonOfField(3, "start_date", pJson["start_date"], err, true))
            return false;
    }

    else
    {
        err="The start_date column cannot be null";
        return false;
    }

    if(pJson.isMember("end_date"))
    {
        if(!validJsonOfField(4, "end_date", pJson["end_date"], err, true))
            return false;
    }

    else
    {
        err="The end_date column cannot be null";
        return false;
    }

    if(pJson.isMember("status"))
    {
        if(!validJsonOfField(5, "status", pJson["status"], err, true))
            return false;
    }

    if(pJson.isMember("updated_by"))
    {
        if(!validJsonOfField(6, "updated_by", pJson["updated_by"], err, true))
            return false;
    }

    if(pJson.isMember("updated_at"))
    {
        if(!validJsonOfField(7, "updated_at", pJson["updated_at"], err, true))
            return false;
    }

    return true;
}
